styles:
.rog-articles .articles-content table th,
    .rog-articles .articles-content table td {
        border-right: 1px solid #474747;
    }

    @media all and (max-width: 992px) {
        .rog-articles .articles-content table {
            width: 100%;
            border: 1px solid #474747;
            border-collapse: collapse;
            border-spacing: 0;
            display: block;
            position: relative;
        }

        .rog-articles .articles-content table thead {
            display: block;
            float: left;
        }

        .rog-articles .articles-content table tbody {
            width: auto;
            display: block;
            position: relative;
            overflow-x: auto;
            white-space: nowrap;
        }

        .rog-articles .articles-content table tr,
        .rog-articles .articles-content table th,
        .rog-articles .articles-content table td {
            border: none;
        }

        .rog-articles .articles-content table th,
        .rog-articles .articles-content table td {
            height: 76px;
            border-bottom: 1px solid #474747;
            border-right: 1px solid #474747;
            display: flex;
            justify-content: center;
            align-items: center;
            font-size: 13px;
            line-height: 1.2;
            padding: 14px 6px;
            vertical-align: middle;
        }

        .rog-articles .articles-content table th:last-child,
        .rog-articles .articles-content table td:last-child {
            border-bottom: none;
        }

        .rog-articles .articles-content table tbody tr {
            margin-right: -6px
        }

        .rog-articles .articles-content table th {
            width: 120px;
        }

        .rog-articles .articles-content table th:first-child {
            border-bottom: none;
        }

        .rog-articles .articles-content table th:nth-child(2) {
            border-top: 1px solid #474747;
        }

        .rog-articles .articles-content table td:first-child,
        .rog-articles .articles-content table td[colspan='1']+td {
            border-top: 1px solid #474747;
        }

        .rog-articles .articles-content table td[colspan='1'] {
            border-bottom: none;
            border-top: none;
            border-right: none;
            border-left: 1px solid #474747;
        }

        .rog-articles .articles-content table tr {
            display: inline-block;
            vertical-align: bottom;
        }

        .rog-articles .articles-content table tr:first-child td:first-child {
            border-left: none;
        }
    }
